mapper.select:
SELECT s.id, s.name, s.description, s.category_id, s.city_code, s.address,
       s.poster_url, s.venue, s.status, s.extend, s.create_time, s.update_time,
       c.name AS category_name, ct.name AS city_name
FROM `show` s
LEFT JOIN category c  ON c.id   = s.category_id
LEFT JOIN city     ct ON ct.code = s.city_code

    AND s.status = #{status}
    AND s.name LIKE CONCAT(#{name}, '%')
    AND s.category_id = #{categoryId}
    AND s.city_code = #{cityCode}
    AND s.venue LIKE CONCAT(#{venue}, '%')

ORDER BY s.create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM `show` s

    AND s.status = #{status}
    AND s.name LIKE CONCAT(#{name}, '%')
    AND s.category_id = #{categoryId}
    AND s.city_code = #{cityCode}
    AND s.venue LIKE CONCAT(#{venue}, '%')
